<?php if ($pages>1): ?><nav class="blog-pagination" aria-label="หน้าบทความ"><?php if ($page>1): ?><a href="?<?= e(http_build_query(array_merge($filters,['page'=>$page-1]))) ?>#journal-stories" aria-label="หน้าก่อนหน้า"><i class="material-icons" aria-hidden="true">arrow_back</i></a><?php endif ?><?php for ($i=1;$i<=$pages;$i++): ?><?php if ($i===1 || $i===$pages || abs($i-$page)<=1): ?><a class="<?= $i===$page ? 'active' : '' ?>" href="?<?= e(http_build_query(array_merge($filters,['page'=>$i]))) ?>#journal-stories" <?= $i===$page ? 'aria-current="page"' : '' ?>><?= $i ?></a><?php elseif (abs($i-$page)===2): ?><span aria-hidden="true">…</span><?php endif ?><?php endfor ?><?php if ($page<$pages): ?><a href="?<?= e(http_build_query(array_merge($filters,['page'=>$page+1]))) ?>#journal-stories" aria-label="หน้าถัดไป"><i class="material-icons" aria-hidden="true">arrow_forward</i></a><?php endif ?></nav><?php endif ?>
